css:
/* THEME 10: ESTATEIN LUXURY (Monochrome Dark Premium) */
@import url('https://fonts.googleapis.com/css2?family=Urbanist:wght@300;400;500;600;700&display=swap');

:root { 
  --primary: #FFFFFF; /* Чистый белый акцент на черном фоне */
  --bg-gradient: #050505; /* Глубочайший матовый черный */
  --card-bg: #111111; 
  --card-dark: #0A0A0A; 
  --text-main: #EFEFEF; 
  --text-muted: #71717A; 
  --border-color: #222222; 
  --radius: 10px; 
  --shadow-sm: none; /* Убираем тени для абсолютно плоского Dark UI */
  --font-main: 'Urbanist', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: var(--font-main); background: var(--bg-gradient); color: var(--text-main); line-height: 1.7; display: flex; flex-direction: column; min-height: 100vh; }
a { text-decoration: none; color: var(--primary); transition: 0.2s; border-bottom: 1px solid transparent; }
a:hover { border-bottom-color: var(--primary); }

.site-header { background: #050505; border-bottom: 1px solid var(--border-color); position: sticky; top: 0; z-index: 1000; }
.header-container { max-width: 1280px; margin: 0 auto; padding: 20px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 15px; }
.logo { font-size: 1.5rem; font-weight: 600; color: #fff; text-transform: uppercase; letter-spacing: 2px; }

.search-input { padding: 12px 18px; border-radius: 6px; border: 1px solid var(--border-color); background: #0A0A0A; color: #fff; width: 320px; font-family: inherit; font-size: 0.95rem; transition: 0.3s; }
.search-input:focus { outline: none; border-color: #555; background: #111; }

.header-nav { display: flex; gap: 30px; align-items: center; font-size: 0.95rem; font-weight: 400; }
.btn-primary { background: #FFFFFF; color: #000; padding: 12px 24px; border-radius: 6px; font-weight: 600; border: none; cursor: pointer; transition: 0.3s; }
.btn-primary:hover { background: #CCCCCC; }

.layout-container { max-width: 1280px; margin: 50px auto; padding: 0 20px; display: flex; flex-direction: column; gap: 40px; flex-grow: 1; width: 100%; }
@media(min-width: 860px) { .layout-container { flex-direction: row; } }
.main-content { flex-grow: 1; width: 100%; }
@media(min-width: 860px) { .main-content { width: 72%; } }
.sidebar { width: 100%; display: flex; flex-direction: column; gap: 24px; }
@media(min-width: 860px) { .sidebar { width: 28%; } }

.card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 30px; }
.widget-title { font-size: 1.2rem; border-bottom: 1px solid var(--border-color); padding-bottom: 15px; margin-bottom: 20px; font-weight: 500; color: #fff; letter-spacing: 0.5px; }

.stat-list li { display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px solid var(--border-color); font-size: 1rem; color: #A1A1AA; font-weight: 300; }
.stat-list li:last-child { border-bottom: none; }

.post-list { display: grid; gap: 24px; }
.post-item { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 30px; transition: 0.2s; }
.post-item:hover { border-color: #444; }
.post-title { font-size: 1.4rem; font-weight: 500; margin-bottom: 12px; color: #fff; letter-spacing: -0.02em; }
.post-meta { display: flex; gap: 20px; font-size: 0.9rem; color: var(--text-muted); margin-top: 10px; font-weight: 300; }

.message-block { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); margin-bottom: 24px; display: flex; flex-direction: column; overflow: hidden; }
@media(min-width: 640px) { .message-block { flex-direction: row; } }
.user-panel { background: var(--card-dark); padding: 25px; display: flex; align-items: center; border-bottom: 1px solid var(--border-color); }
@media(min-width: 640px) { .user-panel { width: 180px; border-bottom: none; border-right: 1px solid var(--border-color); flex-direction: column; text-align: center; flex-shrink: 0; } }
.user-panel img { width: 70px; height: 70px; border-radius: 50%; margin-bottom: 15px; border: 1px solid #333; filter: grayscale(100%); }
.message-content { padding: 30px; flex-grow: 1; font-weight: 300; }
.message-header { display: flex; justify-content: space-between; padding-bottom: 12px; margin-bottom: 20px; font-size: 0.85rem; color: var(--text-muted); border-bottom: 1px solid var(--border-color); }

.badge { background: #222; color: #fff; font-size: 0.75rem; padding: 4px 12px; border-radius: 4px; font-weight: 500; display: inline-block; letter-spacing: 0.5px; border: 1px solid #333; }

.pagination { display: flex; justify-content: center; gap: 8px; margin-top: 50px; }
.page-link { padding: 10px 16px; border: 1px solid var(--border-color); background: transparent; border-radius: 6px; font-weight: 500; color: var(--text-muted); transition: 0.2s; }
.page-link:hover { border-color: #666; color: #fff; }
.page-link.active { background: #fff; color: #000; border-color: #fff; }

.site-footer { background: #050505; padding: 60px 20px; border-top: 1px solid var(--border-color); margin-top: auto; font-size: 0.9rem; color: var(--text-muted); }
.footer-container { max-width: 1280px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 40px; }
